bool DevToolsSession::PrepareAuxDocumentCommand(
    int call_id, const std::optional<std::string>& capability) {
  auto refuse = [&]() {
    DispatchProtocolMessageToClient(crdtp::CreateErrorResponse(call_id,
        crdtp::DispatchResponse::ServerError("Referenced tab document changed; select it again."))->Serialize());
    return false;
