  if (aux_document_calls_.contains(call_id)) return refuse();
  if (capability) {
    if (capability->empty() || capability->size() > 64 ||
        !client_->IsAuthenticatedRemoteDebuggingSession()) return refuse();
    auto* delegate = DevToolsManager::GetInstance()->delegate();
    auto guard = delegate ? delegate->GetAuxDocumentCommandGuard(agent_host_, *capability)
                          : base::RepeatingCallback<bool()>();
    if (!guard || !guard.Run()) return refuse();
    aux_document_guard_ = std::move(guard);
  }
  if (!aux_document_guard_) return true;
  if (!aux_document_guard_.Run()) return refuse();
  aux_document_calls_.emplace(call_id,
      AuxDocumentCallGuard{aux_document_guard_, ++aux_document_serial_});
  return true;
}
bool DevToolsSession::AuxDocumentResponseIsCurrent(int call_id) {
  auto found = aux_document_calls_.find(call_id);
  if (found == aux_document_calls_.end()) return true;
  auto guard = std::move(found->second.current);
  aux_document_calls_.erase(found);
  return guard.Run();
}
void DevToolsSession::RefuseAuxDocumentCommand(int call_id, uint64_t serial) {
  auto guard = aux_document_calls_.find(call_id);
  if (guard == aux_document_calls_.end() || guard->second.serial != serial) return;
  aux_document_calls_.erase(guard);
  auto pending = waiting_for_response_.find(call_id);
  if (pending != waiting_for_response_.end()) {
    pending_messages_.erase(pending->second);
    waiting_for_response_.erase(pending);
  }
  DispatchProtocolMessageToClient(crdtp::CreateErrorResponse(call_id,
      crdtp::DispatchResponse::ServerError("Referenced tab document changed; select it again."))->Serialize());
}

